mapper.delete:
DELETE FROM pcd_tag_table
WHERE tag_id = #{tag_id}
  AND tag_user_id = #{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}

mapper.update:
UPDATE pcd_tag_table
SET tag_name = #{tag_name},
    tag_color = #{tag_color}
WHERE tag_id = #{tag_id}
  AND tag_user_id = #{tag_user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}

mapper.select:
SELECT * FROM pcd_tag_table
WHERE tag_user_id = #{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND tag_name = #{tag_name}

